const current = $input.item.json;
const msg = $('Telegram Trigger').item.json.message;
const threadId = msg.message_thread_id ?? msg.chat.id;
const isRealReply = msg.reply_to_message && msg.reply_to_message.message_id !== threadId;
const replyToMessageId = isRealReply ? msg.reply_to_message.message_id : threadId;

// Convert a sheet's row objects (keyed by column letter, e.g. A/B/C) into
// readable "Header: value" lines, using the sheet's first row as headers.
function sheetToText(sheetName, rows) {
  if (!Array.isArray(rows) || rows.length === 0) return `Sheet: ${sheetName}\n(empty)`;
  const headerRow = rows[0];
  const cols = Object.keys(headerRow);
  const lines = rows.slice(1).map(row =>
    cols.map(col => `${headerRow[col] ?? col}: ${row[col] ?? ''}`).join(' | ')
  );
  return `Sheet: ${sheetName}\n${lines.join('\n')}`;
}

function fileToText(f) {
  if (typeof f.text === 'string' && f.text.trim()) return f.text;
  if (f.sheets && typeof f.sheets === 'object') {
    return Object.entries(f.sheets)
      .map(([sheetName, rows]) => sheetToText(sheetName, rows))
      .join('\n\n');
  }
  return '';
}

let extractedText = '';
if (current.content?.parts) {
  // "Analyze document" (Gemini) output
  extractedText = current.content.parts.map(p => p.text || '').join('\n');
} else if (Array.isArray(current.files)) {
  // "Convert File to JSON" output — handles both text-bearing files
  // (docx/pdf) and spreadsheet files (xlsx/csv, which return `sheets`)
  extractedText = current.files.map(fileToText).join('\n\n');
}

const senderName = [msg.from.first_name, msg.from.last_name].filter(Boolean).join(' ');
const memberCaption = (msg.caption || '').trim();
const combinedText = memberCaption
  ? `${senderName} : ${memberCaption} || The Document Text: \n\n${extractedText}`
  : extractedText;

return [{
  json: {
    chat_id: msg.chat.id,
    thread_id: threadId,
    message_id: msg.message_id,
    sender_name: senderName,
    username: msg.from.username || null,
    created_at_gmt7: new Date(msg.date * 1000).toLocaleString('sv-SE', { timeZone: 'Asia/Jakarta' }),
    reply_to_message_id: replyToMessageId,
    document_id: msg.message_id,
    file_name: msg.document.file_name,
    blobType: msg.document.mime_type,
    caption: memberCaption || null,
    extracted_text: combinedText.trim()
  }
}];

const fileName = $json.message.document.file_name;
const allowedExtensions = ['docx', 'xml', 'yml', 'xlsx', 'csv', 'pdf', 'txt', 'pptx', 'html'];

// Extract extension (handles files without extension or lowercase/uppercase differences)
const extension = fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : '';

// Check if supported
const isSupported = allowedExtensions.includes(extension);

return {
  file_name: fileName,
  extension: extension,
  is_supported: isSupported
};

