const items = $input.all();
let contextBlock = '';
const sourceLinks = {};

items.forEach((item, index) => {
  const num = index + 1;
  const meta = item.json.metadata || {};
  const chatId = String(meta.chat_id || '').replace(/^-100/, '');
  const messageId = meta.message_id;
  const sender = meta.sender_name || meta.username || 'unknown';

  contextBlock += `[${num}] ${sender}: ${item.json.content}\n\n`;

  if (chatId && messageId) {
    sourceLinks[num] = `https://t.me/c/${chatId}/${messageId}`;
  }
});

return { json: { context: contextBlock, sourceLinks } };

function sanitizeTelegramHtml(html) {
  let out = html;
  // Convert list markup to bullet lines, in case the model still emits it
  out = out.replace(/<li[^>]*>/gi, '• ');
  out = out.replace(/<\/li>/gi, '\n');
  out = out.replace(/<\/?(ul|ol)[^>]*>/gi, '');
  // Common block-level tags become line breaks
  out = out.replace(/<br\s*\/?>/gi, '\n');
  out = out.replace(/<\/p>/gi, '\n');
  out = out.replace(/<p[^>]*>/gi, '');
  out = out.replace(/<\/?div[^>]*>/gi, '');
  out = out.replace(/<\/?(h[1-6]|span|table|tr|td|th|thead|tbody)[^>]*>/gi, '');
  // Strip anything not in Telegram's actual whitelist
  const allowed = ['b', 'strong', 'i', 'em', 'u', 'ins', 's', 'strike', 'del', 'a', 'code', 'pre', 'blockquote', 'tg-spoiler'];
  out = out.replace(/<\/?([a-zA-Z0-9-]+)([^>]*)>/g, (match, tag) => {
    return allowed.includes(tag.toLowerCase()) ? match : '';
  });
  return out;
}

const answer = $input.first().json.content.parts[0].text;
const sourceLinks = $('Get Source Link').first().json.sourceLinks;

let linkedAnswer = answer.replace(/\[(\d+)\]/g, (match, num) => {
  const url = sourceLinks[num];
  return url ? `<a href="${url}">[${num}]</a>` : match;
});

linkedAnswer = sanitizeTelegramHtml(linkedAnswer);

return { json: { ...$json, linkedAnswer } };

