const stopwords = new Set([
  'yang','dari','siapa','apa','ke','di','dan','atau','ini','itu','untuk',
  'dengan','saja','aja','dong','sih','ya','nya','adalah','akan','bisa',
  'ada','tersebut','pada','juga','saat','kapan','berapa','bagaimana',
  'who','what','where','when','is','are','the','a','an','from','of',
  'in','on','to','for','and','or','how','much','many','does','did','ask'
]);

const question = ($json.query || '').toLowerCase();

const tokens = question.match(/\d+(\.\d+)?|[a-z]+/g) || [];
const keywords = tokens.filter(w => w.length >= 3 && !stopwords.has(w));

const keywordPattern = keywords.join(' | ');

return { json: { ...$json, keywordPattern } };

// Process every item in the input batch
return $input.all().map(item => {
  // Grab raw text buffer from binary data 'data'
  const binaryData = item.binary?.data?.data 
    ? Buffer.from(item.binary.data.data, 'base64') 
    : Buffer.from('');

  // Extract raw ASCII string
  const rawText = binaryData.toString('utf-8');

  // Strip non-printable control characters
  const cleanText = rawText.replace(/[^\x20-\x7E\n\r]/g, '');

  return {
    json: {
      ...item.json,
      extractedText: cleanText,
      // Check if text length is greater than 50 characters
      isSearchable: cleanText.trim().length > 10
    },
    // Retain binary property so downstream nodes can still use the file if needed
    binary: item.binary
  };
});

