// 1. Get all items from the previous SQL node
let items = $input.all();

// Sort by date: Newest (latest) at the top
items.sort((a, b) => new Date(b.json.payment_date) - new Date(a.json.payment_date));

// Helper to escape HTML characters safely for Telegram
const escapeHtml = (str) => 
  (str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

// Get payDesc from the first item, fallback if missing
const title = escapeHtml(items[0]?.json?.payDesc || 'Payments');

let message = `💳 <b>${title}</b>\n\n`;

// 2. Loop through each item
items.forEach((item) => {
  const p = item.json;

  // Format date to "Jul 15, 2026"
  const date = new Date(p.payment_date).toLocaleDateString('en-US', {
    month: 'short',
    day: '2-digit',
    year: 'numeric'
  });

  const sender = escapeHtml(p.sender);

  // Extract Amount and From fields from content
  const amountMatch = p.content.match(/Amount:\s*([^|]+)/i);
  const fromMatch = p.content.match(/From:\s*([^|]+)/i);

  let detail = '';

  if (amountMatch) {
    const amount = amountMatch[1].trim();
    const from = fromMatch ? fromMatch[1].trim() : '';

    // If 'From' exists: "33210 IDR from Uber", otherwise just "$307.91"
    detail = from ? `${amount} from ${from}` : amount;
  } else {
    // Clean fallback if "Amount:" tag isn't explicitly present
    detail = p.content
      .replace(/^(Pending payment|Verified payout proof|Invoice \/ Bill)\s*—\s*/gi, '')
      .replace(/\b(Method|Amount|From):[^|]*\|\s*/gi, '')
      .replace(/\s*\|\s*(Date|Posted by):[^|]*/gi, '')
      .trim();
  }

  // Uniform Output: Aug 19, 2026 : Dikta — 33210 IDR from Uber
  message += `<b>${date}</b> : <b>${sender}</b> — ${escapeHtml(detail)}\n`;
});

// 3. Return as an array of objects for n8n
return [
  {
    json: {
      telegram_message: message.trim()
    }
  }
];

